sets={}
def t(n,groups,gaps=None):
    original=S['mandatoryTermSets'][n-1]; terms=original['terms']; entries={}
    for indices,ords,why in groups:
        for i in indices:
            ids=[G[o]['id'] for o in ords]
            assert all(x in P for x in ids)
            entries[i]={'term':terms[i-1],'status':'AUTHOR_term_use_candidate_pending_independent_review','canonicalGoalIds':ids,'useRationaleDe':why,'wholeProfileAnchors':[{'goalId':x,'expectationIds':[e['id'] for e in P[x]['expectations']],'applicationCaseIds':[a['id'] for a in P[x]['applicationCaseBriefs']]} for x in ids]}
    for i,why in (gaps or {}).items():entries[i]={'term':terms[i-1],'status':'HOLD_term_use_gap','canonicalGoalIds':[],'missingUseDe':why}
    assert set(entries)==set(range(1,len(terms)+1)),(n,set(range(1,len(terms)+1))-set(entries))
    sets[n]={'termSetId':original['termSetId'],'sourceScopeExact':{k:v for k,v in original.items() if k not in ['terms','sourceGoalIds','carrierStatus']},'sourceGoalIds':original['sourceGoalIds'],'termCount':len(terms),'status':'AUTHOR_candidates_with_finite_gaps' if gaps else 'AUTHOR_term_use_candidates_pending_independent_review','terms':[entries[i] for i in sorted(entries)],'createsAdditionalGoalAtoms':False,'addsUnprintedPerformanceOperators':False}

